                return Err(DurableLedgerError::Corrupt);
            }
            let next = decode_frontier(&frame[..FRAME - 32])?;
            validate_advance(frontier, next)?;
            frontier = next;
            history_digest = extend_history_digest(history_digest, &frame);
            cursor += FRAME as u64;
        }
        if cursor != length {
            file.set_len(cursor)
                .and_then(|()| file.sync_all())
                .map_err(|_| DurableLedgerError::Indeterminate)?;
        }
        file.seek(SeekFrom::Start(cursor))?;
        Ok(Self {
            file,
            binding,
            frontier,
            length: cursor,
            history_digest,
            poisoned: false,
        })
    }

    #[must_use]
    pub const fn binding(&self) -> Digest32 {
        self.binding
    }

    #[cfg(feature = "qualification-legacy-write")]
    pub(crate) fn qualification_file_bytes(
        &mut self,
        maximum_bytes: u64,
    ) -> Result<Vec<u8>, DurableLedgerError> {
        if self.poisoned {
            return Err(DurableLedgerError::Poisoned);
        }
        let bytes = self.file.qualification_bytes(maximum_bytes);
        if matches!(&bytes, Err(DurableLedgerError::Io(_))) {
            self.poisoned = true;
        }
        bytes
    }

    pub fn frontier(&self) -> Result<LedgerWitnessFrontier, DurableLedgerError> {
        if self.poisoned {
            Err(DurableLedgerError::Poisoned)
        } else {
            Ok(self.frontier)
        }
    }

    /// Re-read this original locked witness without repairing, syncing or
    /// releasing its handle. The in-memory fingerprint covers every admitted
    /// frame, including historical frames before the current frontier.
    /// A changed file fences this owner; restoring bytes cannot rearm it.
    pub(crate) fn read_current_frontier(
        &mut self,
    ) -> Result<LedgerWitnessFrontier, DurableLedgerError> {
        if self.poisoned {
            return Err(DurableLedgerError::Poisoned);
        }
        let position = match self.file.stream_position() {
            Ok(position) => position,
            Err(error) => {
                self.poisoned = true;
                return Err(error.into());
            }
        };
        let checked = (|| {
            let length = self.file.metadata()?.len();
            // A durable ledger admits at most 8,192 records. Keep this read
            // bounded independently of attacker-controlled on-disk metadata.
            if length > HEADER as u64 + 8192 * FRAME as u64 {
                return Err(DurableLedgerError::Capacity);
            }
            if length != self.length {
                return Err(DurableLedgerError::Corrupt);
            }
            if length < HEADER as u64 || (length - HEADER as u64) % FRAME as u64 != 0 {
                return Err(DurableLedgerError::IncompleteTail);
            }
            self.file.seek(SeekFrom::Start(0))?;
            let mut header = [0_u8; HEADER];
            self.file.read_exact(&mut header)?;
            if &header[..8] != MAGIC
                || &header[8..40] != self.binding.as_array()
                || Digest32::of_bytes(&header[..40]).as_array() != &header[40..]
            {
                return Err(DurableLedgerError::BindingMismatch);
            }
            let mut frontier = LedgerWitnessFrontier::empty();
            let mut history = Digest32::of_bytes(&header);
            for _ in 0..((length - HEADER as u64) / FRAME as u64) {
                let mut frame = [0_u8; FRAME];
                self.file.read_exact(&mut frame)?;
                if Digest32::of_bytes(&frame[..FRAME - 32]).as_array() != &frame[FRAME - 32..] {
                    return Err(DurableLedgerError::Corrupt);
                }
                let next = decode_frontier(&frame[..FRAME - 32])?;
                validate_advance(frontier, next)?;
                frontier = next;
                history = extend_history_digest(history, &frame);
            }
            if self.file.metadata()?.len() != length
                || frontier != self.frontier
                || history != self.history_digest
            {
                return Err(DurableLedgerError::AnchorMismatch);
            }
            Ok(frontier)
        })();
        // Restoring the original cursor is mandatory even after rejection.
        let restored = self.file.seek(SeekFrom::Start(position));
        let result = match restored {
            Ok(_) => checked,
            Err(error) => Err(error.into()),
        };
        if result.is_err() {
            self.poisoned = true;
        }
        result
    }

    /// Advance exactly one acknowledged ledger record, or replay the exact same
    /// frontier idempotently. Sync completes before the in-memory frontier moves.
    pub fn advance(
        &mut self,
        expected: LedgerWitnessFrontier,
        next: LedgerWitnessFrontier,
    ) -> Result<LedgerWitnessFrontier, DurableLedgerError> {
        if self.poisoned {
            return Err(DurableLedgerError::Poisoned);
        }
        if self.frontier != expected {
            return Err(DurableLedgerError::Conflict);
        }
        if next == expected {
            return Ok(next);
        }
        validate_advance(expected, next)?;
        let frame = encode_frontier(next)?;
        self.poisoned = true;
        if self.file.seek(SeekFrom::End(0))? != self.length {
            return Err(DurableLedgerError::Corrupt);
        }
        self.file
            .write_all(&frame)
            .and_then(|()| self.file.sync_all())
            .map_err(|_| DurableLedgerError::Indeterminate)?;
        self.length += frame.len() as u64;
        self.history_digest = extend_history_digest(self.history_digest, &frame);
        self.frontier = next;
        self.poisoned = false;
        Ok(next)
    }
}

fn extend_history_digest(previous: Digest32, frame: &[u8]) -> Digest32 {
    Digest32::of_parts(&[
        b"hepta.learning-witness.original-history.v1\0",
        previous.as_array(),
        frame,
    ])
}

fn validate_binding(binding: Digest32) -> Result<(), DurableLedgerError> {
    if binding.is_zero() {
        Err(DurableLedgerError::InvalidBinding)
    } else {
        Ok(())
    }
}

fn validate_advance(
    previous: LedgerWitnessFrontier,
    next: LedgerWitnessFrontier,
) -> Result<(), DurableLedgerError> {
    if next.anchor.chain_digest.is_zero() {
        return Err(DurableLedgerError::InvalidAnchor);
    }

    if next.anchor.sequence == previous.anchor.sequence {
        if next.anchor.chain_digest != previous.anchor.chain_digest {
            return Err(DurableLedgerError::InvalidAnchor);
        }
        return match (previous.segment, next.segment) {
            (Some(previous_segment), Some(next_segment))
                if next_segment == previous_segment && !previous.sealed && next.sealed =>
            {
                Ok(())
            }
            (Some(previous_segment), Some(next_segment))
                if next_segment == previous_segment + 1 && !next.sealed =>
            {
                Ok(())
            }
            _ => Err(DurableLedgerError::InvalidAnchor),
        };
    }

    let expected_sequence = previous
        .anchor
        .sequence
        .checked_add(1)
        .ok_or(DurableLedgerError::InvalidAnchor)?;
    if next.anchor.sequence != expected_sequence {
        return Err(DurableLedgerError::InvalidAnchor);
    }
    match (previous.segment, next.segment) {
        (None, None) => {}
        (None, Some(0)) => {}
        (Some(previous_segment), Some(next_segment)) if next_segment == previous_segment => {}
        _ => return Err(DurableLedgerError::InvalidAnchor),
    }
    Ok(())
}

fn encode_frontier(frontier: LedgerWitnessFrontier) -> Result<Vec<u8>, DurableLedgerError> {
    let segment = match frontier.segment {
        Some(segment) => u64::try_from(segment).map_err(|_| DurableLedgerError::InvalidAnchor)?,
        None => NO_SEGMENT,
    };
    let mut bytes = Vec::with_capacity(FRAME);
    bytes.extend_from_slice(&frontier.anchor.sequence.to_be_bytes());
    bytes.extend_from_slice(&segment.to_be_bytes());
    bytes.push(u8::from(frontier.sealed));
    bytes.extend_from_slice(&[0_u8; 7]);
    bytes.extend_from_slice(frontier.anchor.chain_digest.as_array());
    let checksum = Digest32::of_bytes(&bytes);
    bytes.extend_from_slice(checksum.as_array());
    Ok(bytes)
}

fn decode_frontier(bytes: &[u8]) -> Result<LedgerWitnessFrontier, DurableLedgerError> {
    if bytes.len() != FRAME - 32 || bytes[17..24].iter().any(|value| *value != 0) {
        return Err(DurableLedgerError::Corrupt);
    }
    let sequence = u64::from_be_bytes(
        bytes[0..8]
            .try_into()
            .map_err(|_| DurableLedgerError::Corrupt)?,
    );
    let raw_segment = u64::from_be_bytes(
        bytes[8..16]
            .try_into()
            .map_err(|_| DurableLedgerError::Corrupt)?,
    );
    let sealed = match bytes[16] {
        0 => false,
        1 => true,
        _ => return Err(DurableLedgerError::Corrupt),
    };
    let segment = if raw_segment == NO_SEGMENT {
        None
    } else {
        Some(usize::try_from(raw_segment).map_err(|_| DurableLedgerError::Corrupt)?)
    };
    let chain_digest = Digest32::from_array(
        bytes[24..56]
            .try_into()
            .map_err(|_| DurableLedgerError::Corrupt)?,
    );
    Ok(LedgerWitnessFrontier {
        anchor: LedgerAnchor {
            sequence,
            chain_digest,
        },
        segment,
        sealed,
    })
}

